# ! [feature (const_generics)] use core :: iter :: FromIterator ; pub struct Struct < const N : usize > ([usize ; N]) ; impl < const N : usize > FromIterator < usize > for Struct < { N } > { # [inline] fn from_iter < I > (iter : I) -> Self where I : IntoIterator < Item = usize > , { let mut array : [usize ; N] = [0 ; N] ; iter . into_iter () . take (N) . enumerate () . for_each (| (idx , elem) | array [idx] = elem) ; Self (array) } }